/**
 * @brief A trie (prefix tree) node with children stored in an unordered_map.
 */
struct TrieNode {
    std::unordered_map<char, TrieNode*> children;
    bool is_end = false;
    ~TrieNode() { for (auto& [c, child] : children) delete child; }
};

/**
 * @brief Trie data structure supporting insert and search.
 *
 * insert(word): Inserts a word into the trie, creating new nodes as needed.
 *   Each character of the word becomes a child node. The last node is marked
 *   as a word-end.
 *
 * search(word): Returns true only if the exact complete word was previously
 *   inserted. A prefix that was not inserted as a complete word returns false.
 */
class Trie {
public:
    TrieNode root;

    void insert(const std::string& word) {

golden_completion:
TrieNode* node = &root;
for (char c : word) {
    if (node->children.find(c) == node->children.end()) {
        node->children[c] = new TrieNode();
    }
    node = node->children[c];
}
node->is_end = true;

suffix:
    }

    bool search(const std::string& word) const {
        const TrieNode* node = &root;
        for (char c : word) {
            auto it = node->children.find(c);
            if (it == node->children.end()) return false;
            node = it->second;
        }
        return node->is_end;
    }
};

int main() {
    Trie trie;
    trie.insert("apple");
    trie.insert("app");
    assert(trie.search("apple") == true);
    assert(trie.search("app") == true);
    assert(trie.search("ap") == false);
    assert(trie.search("application") == false);
    return 0;
}

