/**
 * @brief Finds the kth smallest element (0-indexed) in an unsorted vector
 *        using the quickselect algorithm.
 *
 * Partitions the vector around a pivot (last element). Elements smaller
 * than the pivot go to the left partition. If the pivot lands at index k,
 * return it. Otherwise recurse into the appropriate partition.
 *
 * @param nums The vector (will be modified in place during partitioning).
 * @param left Left bound of the current partition (inclusive).
 * @param right Right bound of the current partition (inclusive).
 * @param k The target index (0-indexed smallest).
 * @return The kth smallest element.
 */
int quickselect(std::vector<int>& nums, int left, int right, int k) {

golden_completion:
int pivot = nums[right];
int store = left;
for (int i = left; i < right; ++i) {
    if (nums[i] < pivot) {
        std::swap(nums[i], nums[store]);
        ++store;
    }
}
std::swap(nums[store], nums[right]);
if (store == k) return nums[store];
if (store < k) return quickselect(nums, store + 1, right, k);
return quickselect(nums, left, store - 1, k);

suffix:
}

int main() {
    std::vector<int> v1 = {3, 1, 4, 1, 5, 9, 2, 6};
    assert(quickselect(v1, 0, v1.size()-1, 0) == 1);
    std::vector<int> v2 = {3, 1, 4, 1, 5, 9, 2, 6};
    assert(quickselect(v2, 0, v2.size()-1, 3) == 3);
    std::vector<int> v3 = {7};
    assert(quickselect(v3, 0, 0, 0) == 7);
    return 0;
}

